#!/usr/bin/env python3
"""Configure this decompilation project (generated by romwright new-project).

    python3 configure.py                  fetch tools, `dtk dol split`, write build.ninja + objdiff.json
    python3 configure.py swap NAME|ADDR   give one function a C translation unit (see README.md)
    ninja                                 link, rebuild the DOL, check it against build.sha1
    ninja rels                            link the RELs, `dtk rel make`, check them against rels.sha1
    ninja progress                        objdiff report (build/<version>/report.json)

Tools come from `config/toolchain.json`, a pinned manifest (url + sha256 per tool)
that `tools/download_tool.py` fetches into build/tools/ and verifies. A toolchain
profile (`--toolchain FILE`, or config/toolchain.local.json) replaces any tool with
one you already have installed: keys `dtk`, `wibo`, `compiler` (mwcceppc.exe),
`linker` (mwldeppc.exe), `sjiswrap`, `objdiff-cli`.

The shape follows decomp-toolkit's dtk-template: dtk splits the DOL into one
relocatable object per translation unit (assembly-only for the gaps), Metrowerks'
linker puts them back at the retail addresses under dtk's generated ldscript, and
`dtk elf2dol` / `dtk rel make` write the DOL and RELs.
"""
import argparse
import hashlib
import json
import os
import re
import shlex
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT / "tools"))
import download_tool  # noqa: E402

PROJECT = json.loads((ROOT / "config" / "project.json").read_text())
VERSION = PROJECT["version"]
DTK_CONFIG = ROOT / PROJECT["dtk"]["config"]
SYMBOLS = ROOT / PROJECT["dtk"]["symbols"]
SPLITS = ROOT / PROJECT["dtk"]["splits"]
OBJECTS = ROOT / PROJECT["dtk"]["objects"]
BUILD_SHA1 = PROJECT["dtk"]["build_sha1"]
BUILD = ROOT / "build"
OUT = f"build/{VERSION}"
LOCAL_PROFILE = ROOT / "config" / "toolchain.local.json"
WINDOWS = os.name == "nt"
MAX_PASSES = 3
MAX_DROPS = 60


# --------------------------------------------------------------------------
# Tools
# --------------------------------------------------------------------------

class Tools:
    def __init__(self):
        self.dtk = None
        self.launcher = []     # wibo (empty on Windows)
        self.compilers = None  # install dir of the compilers bundle, or None when `compiler` was given
        self.given = {}
        self.sjiswrap = None
        self.objdiff = None
        self.env = {}

    def compiler_dir(self, mw_version):
        if "compiler" in self.given:
            return Path(self.given["compiler"]).parent
        return self.compilers / mw_version

    def cc(self, mw_version):
        if "compiler" in self.given:
            return self.given["compiler"]
        return str(self.compiler_dir(mw_version) / "mwcceppc.exe")

    def ld(self, mw_version):
        if "linker" in self.given:
            return self.given["linker"]
        return str(self.compiler_dir(mw_version) / "mwldeppc.exe")


def load_profile(path):
    profile = json.loads(Path(path).read_text())
    for key, entry in (profile.get("tools") or {}).items():
        digest = (entry.get("digest") or "").lower()
        if digest and len(digest) == 64:
            actual = download_tool.sha256_file(entry["path"])
            if actual != digest:
                raise SystemExit(f"{path}: tool `{key}` ({entry['path']}) sha256 {actual} != profile digest {digest}")
    return profile


def resolve_tools(args):
    manifest = download_tool.load_manifest(args.manifest or ROOT / "config" / "toolchain.json")
    spec = PROJECT["tools"]
    profile_path = args.toolchain or (LOCAL_PROFILE if LOCAL_PROFILE.exists() else None)
    profile = load_profile(profile_path) if profile_path else {}
    given = {key: entry["path"] for key, entry in (profile.get("tools") or {}).items()}
    tools = Tools()
    tools.given = given
    tools.env = dict((profile.get("recipe") or {}).get("environment") or {})

    def where(tool_id):
        if args.no_tools:
            return BUILD / "tools" / tool_id
        return download_tool.install(manifest[tool_id], BUILD / "tools", BUILD / "tools" / ".cache")

    tools.dtk = given.get("dtk") or str(where(spec["dtk"]) / manifest[spec["dtk"]]["provides"]["dtk"])
    if not WINDOWS:
        tools.launcher = [given.get("wibo") or str(where("wibo") / "wibo")]
    if "compiler" not in given:
        tools.compilers = where(spec["compiler"])
    else:
        tools.compilers = None
    if "sjiswrap" in given:
        tools.sjiswrap = given["sjiswrap"]
    elif not args.no_tools:
        tools.sjiswrap = str(where(spec["sjiswrap"]) / "sjiswrap.exe")
    if "objdiff-cli" in given:
        tools.objdiff = given["objdiff-cli"]
    elif spec.get("report") and not args.no_tools:
        try:
            tools.objdiff = str(where(spec["report"]) / "objdiff-cli")
        except SystemExit as error:
            print(f"warning: objdiff-cli unavailable ({error}); `ninja progress` is disabled", file=sys.stderr)
    return tools


# --------------------------------------------------------------------------
# dtk split
# --------------------------------------------------------------------------

def sha1_bytes(data):
    return hashlib.sha1(data).hexdigest()


def split_inputs():
    paths = [DTK_CONFIG, SYMBOLS, SPLITS, OBJECTS.parent / "build.sha1"]
    for module in PROJECT.get("modules", []):
        base = SYMBOLS.parent / "modules" / module["name"]
        paths += [base / "symbols.txt", base / "splits.txt"]
    return [p for p in paths if p.exists()]


def split_state():
    digest = hashlib.sha1()
    for path in split_inputs():
        digest.update(path.read_bytes() + b"\0")
    digest.update(PROJECT["dtk"]["version"].encode())
    return digest.hexdigest()


OVERLAP = re.compile(r"Overlapping functions \d+:0x([0-9A-Fa-f]+)-\S+ -> \d+:0x([0-9A-Fa-f]+)")
ENDS_WITHIN = re.compile(r"ends within symbol '([^']+)'")
SYMBOL_OVERLAPS = re.compile(r"Symbol (\S+) \(0x[0-9A-Fa-f]+\.\.0x[0-9A-Fa-f]+\) overlaps with symbol")
UNPAIRED = re.compile(r"Unpaired epilogue \d+:0x([0-9A-Fa-f]+)")
UNALIGNED = re.compile(r"Unaligned symbol entry @ 0x([0-9A-Fa-f]+)")
MULTIPLE_INSIDE = re.compile(r"While processing \d+:0x([0-9A-Fa-f]+): FunctionSlices")
ROW_AT = re.compile(r"^(\S+) = (\.\w+):0x([0-9A-Fa-f]+);")


def drop_symbol(error):
    """romwright's symbols are advice and dtk's analysis is the authority on what it can split:
    when dtk refuses a symbol row (a function lies inside one dtk's control-flow analysis found,
    an auto-generated split ends inside it, its size runs over another symbol or over two
    functions, or it is an object at an address dtk cannot place), take that row out. Returns the
    dropped row, or None when the error names no row of symbols.txt."""
    candidates = []   # (address, name) keys to look for, in order
    if match := OVERLAP.search(error):
        # the function inside, else the one that contains it
        candidates = [("address", int(match.group(2), 16)), ("address", int(match.group(1), 16))]
    elif match := ENDS_WITHIN.search(error) or SYMBOL_OVERLAPS.search(error):
        candidates = [("name", match.group(1))]
    elif ("Found multiple functions inside a symbol" in error or "Failed to locate section @" in error) and (
            match := MULTIPLE_INSIDE.search(error)):
        # the function dtk was following when it found two inside it, or ran into an unmapped address
        candidates = [("address", int(match.group(1), 16))]
    elif match := UNPAIRED.search(error):
        candidates = [("containing", int(match.group(1), 16))]
    elif match := UNALIGNED.search(error):
        candidates = [("anywhere", int(match.group(1), 16))]
    rows = SYMBOLS.read_text().split("\n")
    for kind, key in candidates:
        for index, row in enumerate(rows):
            found = ROW_AT.match(row)
            if not found:
                continue
            if kind == "name":
                hit = found.group(1) == key
            elif kind == "containing":
                size = re.search(r"size:0x([0-9A-Fa-f]+)", row)
                start = int(found.group(3), 16)
                hit = "type:function" in row and size is not None and start <= key < start + int(size.group(1), 16)
            else:
                hit = int(found.group(3), 16) == key and (kind == "anywhere" or "type:function" in row)
            if hit:
                del rows[index]
                SYMBOLS.write_text("\n".join(rows))
                return row
    return None


def dtk_split(tools):
    dropped = BUILD / VERSION / "dropped-symbols.txt"
    seen = set()
    for attempt in range(MAX_DROPS):
        result = subprocess.run([tools.dtk, "dol", "split", str(DTK_CONFIG.relative_to(ROOT)), OUT], cwd=ROOT,
                                stderr=subprocess.PIPE, text=True)
        sys.stderr.write("".join(line + "\n" for line in result.stderr.splitlines() if " WARN " not in line))
        if result.returncode == 0:
            return
        row = drop_symbol(result.stderr)
        if row is None or row in seen:
            # nothing to drop, or dtk writes the same row back each pass: dropping it cannot help
            raise SystemExit(f"dtk dol split failed (exit {result.returncode})")
        seen.add(row)
        dropped.parent.mkdir(parents=True, exist_ok=True)
        with open(dropped, "a") as handle:
            handle.write(row + "\n")
        print(f"dtk cannot split with `{row.split(' = ')[0]}`: row dropped from symbols.txt (build/{VERSION}/dropped-symbols.txt)", flush=True)
    raise SystemExit(f"dtk dol split still fails after dropping {MAX_DROPS} symbols")


def ensure_ctors_unit():
    """Metrowerks' startup registers `__init_cpp_exceptions` as the first `.ctors` entry. dtk gives
    it a unit of its own (`__init_cpp_exceptions.cpp`, `.ctors$10` orders it first, with its
    extab entries) when its signature matches the function's boundaries; when it does not, the
    entry falls in text order and the rebuilt DOL differs. Add a unit holding that `.ctors`
    piece when dtk made none. True when added."""
    start = (PROJECT.get("runtime") or {}).get("ctors_start")
    if not start:
        return False
    config_json = ROOT / OUT / "config.json"
    if config_json.exists() and any("__init_cpp_exceptions" in u["name"] for u in json.loads(config_json.read_text())["units"]):
        return False
    text = SPLITS.read_text()
    if re.search(rf"\.ctors\s+start:0x{start:08X}", text, re.I):
        return False
    SPLITS.write_text(text.rstrip("\n") + f"\n\n{RUNTIME_UNIT}:\n\t.ctors      start:0x{start:08X} end:0x{start + 4:08X} rename:.ctors$10\n")
    return True


def run_split(tools, force):
    original = ROOT / PROJECT["image"]["orig"]
    if not original.exists():
        raise SystemExit(f"{original}: the retail DOL is missing; put your own copy there")
    if sha1_bytes(original.read_bytes()) != PROJECT["image"]["sha1"]:
        raise SystemExit(f"{original}: sha1 is not the {PROJECT['image']['sha1']} this project was generated from")
    config_json = ROOT / OUT / "config.json"
    stamp = BUILD / ".split-stamp"
    if not force and config_json.exists() and stamp.exists() and stamp.read_text() == split_state():
        return
    print("dtk dol split (this takes a while on a large image)", flush=True)
    BUILD.mkdir(exist_ok=True)
    saved = (SYMBOLS.read_text(), SPLITS.read_text())
    # Metrowerks' startup registrations (`__init_cpp_exceptions`, `__destroy_global_chain`,
    # `__fini_cpp_exceptions`) are handled by dtk differently from game to game; try the
    # arrangements until the DOL rebuilds byte for byte (see `runtime` in config/project.json).
    # `analysis` drops romwright's rows altogether, for a DOL whose rows dtk keeps refusing.
    refused = []
    for attempt in range(2):
        modules = bool(PROJECT.get("modules"))
        order = ["names", "keep", "unit", "analysis"] if modules else ["keep", "unit", "names", "analysis"]
        refused = []
        matched_any = False
        for strategy in order:
            SYMBOLS.write_text(saved[0])
            SPLITS.write_text(saved[1])
            if strategy in ("names", "analysis"):
                if strategy == "analysis":
                    # Last resort: dtk's own analysis, without romwright's rows, when dtk refuses them.
                    SYMBOLS.write_text("")
                apply_names(add_rows=strategy == "analysis")
            try:
                split_passes(tools, strategy == "unit")
                matched = dol_matches(tools)
            except SystemExit as error:
                print(f"arrangement `{strategy}`: dtk refused ({error})", flush=True)
                refused.append(strategy)
                continue
            if matched:
                print(f"the DOL rebuilds byte for byte (arrangement: {strategy})", flush=True)
                matched_any = True
                break
            print(f"arrangement `{strategy}`: the rebuilt DOL differs from the retail one", flush=True)
        if matched_any:
            break
        if modules and len(refused) == len(order) and attempt == 0:
            drop_modules()
            continue
        print("warning: no arrangement of the startup registrations rebuilt the DOL (dtk refused: "
              f"{', '.join(refused) or 'none'}); see README.md", file=sys.stderr)
        SYMBOLS.write_text(saved[0])
        SPLITS.write_text(saved[1])
        split_passes(tools, False)
        break
    # dtk writes its analysis back into symbols.txt / splits.txt: the stamp is of the result.
    stamp.write_text(split_state())


def drop_modules():
    """dtk refused the whole project with its modules (a module graph it cannot resolve: relocations
    into an overlay that shares an id, ...). Build the DOL alone; the RELs are copied from the
    retail files, and the original config.yml is kept as config.yml.with-modules."""
    text = DTK_CONFIG.read_text()
    head, _, _ = text.partition("\nmodules:")
    DTK_CONFIG.with_name("config.yml.with-modules").write_text(text)
    DTK_CONFIG.write_text(head.rstrip("\n") + "\n")
    PROJECT.setdefault("copied_modules", []).extend(PROJECT.get("modules", []))
    PROJECT["modules"] = []
    print("dtk cannot split the DOL with its RELs: modules dropped from config.yml (kept as config.yml.with-modules); the RELs are copied, not rebuilt", flush=True)


def split_passes(tools, add_unit):
    """dtk writes what its analysis found back into symbols.txt / splits.txt, and what it finds
    depends on what is already there (the runtime's `__init_cpp_exceptions_reference` in .ctors
    is only recognised once the symbol file has been through a pass): split until a pass leaves
    the files as it found them, at most MAX_PASSES times."""
    for number in range(1, MAX_PASSES + 1):
        before = split_state()
        dtk_split(tools)
        if split_state() == before:
            break
        print(f"dtk updated the configuration (pass {number})", flush=True)
    if add_unit and ensure_ctors_unit():
        print("dtk made no unit for the first .ctors entry: added one (rename:.ctors$10) and split again", flush=True)
        dtk_split(tools)


RUNTIME_UNIT = "Runtime.PPCEABI.H/__init_cpp_exceptions.c"


def apply_names(add_rows=False):
    """Name the three registered functions after the linker script's symbols and give the three
    entries a unit (`$10`/`$15` are the linker's ordering keys, as in dtk-template projects)."""
    runtime = PROJECT.get("runtime") or {}
    wanted = {runtime.get("ctors_target"): "__init_cpp_exceptions", runtime.get("destroy_target"): "__destroy_global_chain",
              runtime.get("fini_target"): "__fini_cpp_exceptions"}
    rows = SYMBOLS.read_text().split("\n")
    for index, row in enumerate(rows):
        match = ROW_AT.match(row)
        if match and "type:function" in row and int(match.group(3), 16) in wanted and wanted[int(match.group(3), 16)]:
            rows[index] = wanted[int(match.group(3), 16)] + row[len(match.group(1)):]
    if add_rows:
        present = {int(m.group(3), 16) for m in map(ROW_AT.match, rows) if m}
        for address, name in wanted.items():
            if address and address not in present:
                rows.append(f"{name} = .text:0x{address:08X}; // type:function scope:global")
    SYMBOLS.write_text("\n".join(rows))
    pieces = []
    if runtime.get("ctors_start"):
        pieces.append(f"\t.ctors      start:0x{runtime['ctors_start']:08X} end:0x{runtime['ctors_start'] + 4:08X} rename:.ctors$10")
    if runtime.get("dtors_start"):
        start = runtime["dtors_start"]
        pieces.append(f"\t.dtors      start:0x{start:08X} end:0x{start + 4:08X} rename:.dtors$10")
        if runtime.get("fini_target"):
            pieces.append(f"\t.dtors      start:0x{start + 4:08X} end:0x{start + 8:08X} rename:.dtors$15")
    text = SPLITS.read_text()
    if pieces and RUNTIME_UNIT + ":" not in text:
        SPLITS.write_text(text.rstrip("\n") + f"\n\n{RUNTIME_UNIT}:\n" + "\n".join(pieces) + "\n")


def dol_matches(tools):
    """Link dtk's objects and flatten the ELF the way `ninja` will; true when the DOL is the retail one."""
    config = json.loads((ROOT / OUT / "config.json").read_text())
    comp = PROJECT["compiler"]
    rsp, elf, dol = ROOT / OUT / "calibrate.rsp", ROOT / OUT / "calibrate.elf", ROOT / OUT / "calibrate.dol"
    rsp.write_text("\n".join(unit["object"] for unit in config["units"]) + "\n")
    command = [*tools.launcher, tools.ld(comp["linker_version"]), *shlex.split(" ".join(comp["ldflags"])), "-lcf", config["ldscript"],
               "-o", str(elf.relative_to(ROOT)), f"@{rsp.relative_to(ROOT)}"]
    linked = subprocess.run(command, cwd=ROOT, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    if linked.returncode != 0:
        return False
    if subprocess.run([tools.dtk, "elf2dol", str(elf.relative_to(ROOT)), str(dol.relative_to(ROOT))], cwd=ROOT,
                      stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode != 0:
        return False
    return sha1_bytes(dol.read_bytes()) == PROJECT["image"]["sha1"]


# --------------------------------------------------------------------------
# build.ninja
# --------------------------------------------------------------------------

def esc(path):
    return str(path).replace("$", "$$").replace(" ", "$ ").replace(":", "$:")


class Ninja:
    def __init__(self, handle):
        self.out = handle

    def var(self, key, value):
        self.out.write(f"{key} = {value}\n")

    def rule(self, name, command, description, **extra):
        self.out.write(f"rule {name}\n  command = {command}\n  description = {description}\n")
        for key, value in extra.items():
            self.out.write(f"  {key} = {value}\n")
        self.out.write("\n")

    def build(self, outputs, rule, inputs=(), implicit=(), order_only=(), variables=None):
        line = f"build {' '.join(esc(o) for o in outputs)}: {rule} {' '.join(esc(i) for i in inputs)}"
        if implicit:
            line += " | " + " ".join(esc(i) for i in implicit)
        if order_only:
            line += " || " + " ".join(esc(i) for i in order_only)
        self.out.write(line + "\n")
        for key, value in (variables or {}).items():
            self.out.write(f"  {key} = {value}\n")
        self.out.write("\n")


def quote(argv):
    return " ".join(shlex.quote(str(a)).replace("$", "$$") for a in argv)


def headers():
    include = ROOT / "include"
    return sorted(str(p.relative_to(ROOT)) for p in include.rglob("*.h")) if include.exists() else []


def load_objects():
    if not OBJECTS.exists():
        return {}
    return json.loads(OBJECTS.read_text()).get("objects", {})


def cc_command(tools, unit_cfg):
    """MWCC command for one unit (ninja `$in`/`$out`)."""
    comp = PROJECT["compiler"]
    mw_version = unit_cfg.get("mw_version") or comp["mw_version"]
    flags = []
    for flag in (unit_cfg.get("cflags") or comp["cflags"]) + (unit_cfg.get("extra_cflags") or []):
        flags += shlex.split(flag)
    argv = list(tools.launcher)
    if unit_cfg.get("shift_jis") and tools.sjiswrap:
        argv.append(tools.sjiswrap)
    argv.append(tools.cc(mw_version))
    return quote(argv + flags + ["-c"]) + " $in -o $out"


def write_build(tools, config):
    objects = load_objects()
    comp = PROJECT["compiler"]
    scratch = BUILD / "tmp"
    scratch.mkdir(parents=True, exist_ok=True)
    env = {"TMPDIR": str(scratch), "TMP": str(scratch), "TEMP": str(scratch), **tools.env}
    env_prefix = "env " + " ".join(f"{k}={shlex.quote(v)}" for k, v in env.items()) + " "
    ldflags = " ".join(comp["ldflags"])
    link = quote([*tools.launcher, tools.ld(comp["linker_version"])])
    modules = config.get("modules", [])
    compiled = {}   # unit name -> (source, compiled object, dtk object, matching, config)
    with open(ROOT / "build.ninja", "w") as handle:
        n = Ninja(handle)
        n.var("ninja_required_version", "1.7")
        n.var("python", shlex.quote(sys.executable))
        n.out.write("\n")
        n.rule("configure", "$python configure.py", "configure", generator="1")
        cc_rules = {}   # command -> rule name: ninja expands $in/$out in a rule's command only

        def cc_rule(command):
            if command not in cc_rules:
                cc_rules[command] = f"cc{len(cc_rules)}"
                n.rule(cc_rules[command], env_prefix + command, "cc $in")
            return cc_rules[command]

        n.rule("link", link + " $ldflags -o $out @$out.rsp", "link $out", rspfile="$out.rsp", rspfile_content="$in_newline")
        n.rule("elf2dol", quote([tools.dtk, "elf2dol"]) + " $in $out", "dol $out")
        n.rule("makerel", quote([tools.dtk, "rel", "make", "-w"]) + " -c $config $names @$rspfile", "rel $out",
               rspfile="$rspfile", rspfile_content="$in_newline")
        n.rule("check", quote([tools.dtk, "shasum", "-c"]) + " " + BUILD_SHA1 + " -o $out", "check " + BUILD_SHA1)
        n.rule("copy", "$python configure.py copy $in $out", "copy $out")
        n.rule("report", quote([tools.objdiff or "objdiff-cli", "report", "generate"]) + " -o $out", "report")
        configs = [str(p.relative_to(ROOT)) for p in split_inputs()] + [str(OBJECTS.relative_to(ROOT)), "configure.py", "config/project.json"]
        n.build(["build.ninja"], "configure", implicit=configs)

        def add_module(module):
            """Link inputs of one module (the DOL is module 0), compiling units that have C."""
            inputs = []
            for unit in module["units"]:
                dtk_object = unit["object"]
                entry = objects.get(unit["name"])
                source = ROOT / entry["source"] if entry else None
                if entry and source.exists():
                    out = dtk_object.replace("/obj/", "/src/", 1)
                    n.build([out], cc_rule(cc_command(tools, entry)), [entry["source"]], implicit=headers() + ["config/project.json"])
                    compiled[unit["name"]] = (entry["source"], out, dtk_object, bool(entry.get("matching")), entry)
                    inputs.append(out if entry.get("matching") else dtk_object)
                else:
                    inputs.append(dtk_object)
            return inputs

        main_inputs = add_module(config)
        outputs = []
        dol = f"{OUT}/{config['name']}.dol"
        elf = f"{OUT}/{config['name']}.elf"
        n.build([elf], "link", main_inputs, implicit=[config["ldscript"]],
                variables={"ldflags": f"{ldflags} -lcf {config['ldscript']}"})
        n.build([dol], "elf2dol", [elf])
        outputs.append(dol)
        plfs = {config["name"]: (0, elf)}   # `rel make` takes the DOL's ELF first, then each module's PLF
        for module in modules:
            name = module["name"]
            inputs = add_module(module)
            preplf, plf = f"{OUT}/{name}/{name}.preplf", f"{OUT}/{name}/{name}.plf"
            n.build([preplf], "link", inputs, variables={"ldflags": f"{ldflags} -sdata 0 -sdata2 0 -r"})
            entry = f" -m {module['entry']} -strip_partial" if module.get("entry") else ""
            n.build([plf], "link", inputs, implicit=[module["ldscript"], preplf],
                    variables={"ldflags": f"{ldflags} -sdata 0 -sdata2 0 -r1 -lcf {module['ldscript']}{entry}"})
            plfs[name] = (module["module_id"], plf)
        generated = set()
        rel_outputs = []
        links = config.get("links") or ([{"modules": [config["name"], *[m["name"] for m in modules]]}] if modules else [])
        for index, link_group in enumerate(links):
            names = [m for m in link_group["modules"] if m in plfs]
            local = sorted(names, key=lambda m: plfs[m][0])
            fresh = [m for m in local if m not in generated and plfs[m][0] != 0]
            if not fresh:
                continue
            generated.update(fresh)
            rels = [f"{OUT}/{m}/{m}.rel" for m in fresh]
            n.build(rels, "makerel", [plfs[m][1] for m in local], implicit=[str(DTK_CONFIG.relative_to(ROOT))],
                    variables={"config": str(DTK_CONFIG.relative_to(ROOT)), "rspfile": f"{OUT}/rel{index}.rsp",
                               "names": " ".join(f"-n {m}" for m in local)})
            rel_outputs += rels
        # RELs without code cannot be linked; the build copies the retail file.
        for module in PROJECT.get("copied_modules", []):
            copied = f"{OUT}/{module['name']}/{module['name']}.rel"
            n.build([copied], "copy", [module["path"]])
            outputs.append(copied)
        if rel_outputs:
            n.rule("check_rels", quote([tools.dtk, "shasum", "-q", "-c"]) + " " + PROJECT["dtk"]["rels_sha1"] + " -o $out",
                   "check " + PROJECT["dtk"]["rels_sha1"])
            n.build([f"{OUT}/rels_ok"], "check_rels", [], implicit=rel_outputs + [PROJECT["dtk"]["rels_sha1"]])
            n.build(["rels"], "phony", [f"{OUT}/rels_ok"])
        ok = f"{OUT}/ok"
        n.build([ok], "check", [], implicit=outputs + [BUILD_SHA1])
        n.build(["all"], "phony", [ok])
        if tools.objdiff:
            bases = [c[1] for c in compiled.values()]
            n.build([f"{OUT}/report.json"], "report", [], implicit=bases + ["objdiff.json"])
            n.build(["progress"], "phony", [f"{OUT}/report.json"])
        n.out.write("default all\n")
    return compiled


def write_objdiff(config, compiled):
    units = []
    modules = [config, *config.get("modules", [])]
    for module in modules:
        for unit in module["units"]:
            row = {"name": unit["name"], "target_path": unit["object"],
                   "metadata": {"complete": False, "auto_generated": bool(unit.get("autogenerated"))}}
            if unit["name"] in compiled:
                source, base, _, matching, _ = compiled[unit["name"]]
                row["base_path"] = base
                row["metadata"].update({"complete": matching, "source_path": source})
            units.append(row)
    document = {
        "min_version": "2.0.0-beta.5",
        "custom_make": "ninja",
        "build_target": False,
        "build_base": True,
        "watch_patterns": ["src/**/*.c", "src/**/*.cpp", "include/**/*.h", "config/**"],
        "units": units,
    }
    (ROOT / "objdiff.json").write_text(json.dumps(document, indent=2) + "\n")


# --------------------------------------------------------------------------
# swap
# --------------------------------------------------------------------------

ROW = re.compile(r"^(\S+) = (\.\w+):0x([0-9A-Fa-f]+); // type:function size:0x([0-9A-Fa-f]+)", re.M)


def find_function(target):
    for match in ROW.finditer(SYMBOLS.read_text()):
        name, section, address, size = match.group(1), match.group(2), int(match.group(3), 16), int(match.group(4), 16)
        if (re.fullmatch(r"0x[0-9a-fA-F]+", target) and int(target, 16) == address) or name == target:
            return name, section, address, size
    raise SystemExit(f"`{target}` is not a function row of {SYMBOLS.relative_to(ROOT)}")


def unit_blocks(text):
    """`(name, first line, last line exclusive, .text start or None)` of each unit of splits.txt."""
    lines = text.split("\n")
    blocks, current = [], None
    for index, line in enumerate(lines):
        if line and not line[0].isspace() and line.rstrip().endswith(":") and not line.startswith("Sections"):
            if current:
                blocks.append(current)
            current = [line.rstrip()[:-1], index, index + 1, None]
        elif current and line.strip():
            current[2] = index + 1
            m = re.match(r"\s*\.text\s+start:0x([0-9A-Fa-f]+)", line)
            if m:
                current[3] = int(m.group(1), 16)
        elif current and not line.strip():
            blocks.append(current)
            current = None
    if current:
        blocks.append(current)
    return lines, blocks


def swap(args):
    name, section, address, size = find_function(args.function)
    unit = args.unit or f"main/{name}.c"
    text = SPLITS.read_text()
    lines, blocks = unit_blocks(text)
    if any(b[0] == unit for b in blocks):
        print(f"{unit}: already a unit")
    else:
        end = address + size
        insert_at = len(lines)
        for block in blocks:
            if block[3] is not None and block[3] > address:
                insert_at = block[1]
                break
        entry = [f"{unit}:", f"\t{section:<11} start:{address:#010x} end:{end:#010x}", ""]
        if insert_at == len(lines) and lines and lines[-1] == "":
            insert_at -= 1
        lines[insert_at:insert_at] = entry
        SPLITS.write_text("\n".join(lines))
    objects = json.loads(OBJECTS.read_text()) if OBJECTS.exists() else {"objects": {}}
    source = f"src/{unit}"
    objects["objects"].setdefault(unit, {"source": source, "matching": False})
    OBJECTS.write_text(json.dumps(objects, indent=2) + "\n")
    destination = ROOT / source
    destination.parent.mkdir(parents=True, exist_ok=True)
    if args.src:
        shutil.copyfile(args.src, destination)
    elif not destination.exists():
        reference = ROOT / "decompiled" / f"{name}.c"
        body = reference.read_text() if reference.exists() else "/* write the C for this function; objdiff compares it with the retail bytes */\n"
        destination.write_text('#include "romwright_types.h"\n\n' + body)
    print(f"{name}: {unit} -> {source}")
    return unit


def main():
    if sys.argv[1:2] == ["copy"]:
        os.makedirs(os.path.dirname(sys.argv[3]) or ".", exist_ok=True)
        shutil.copyfile(sys.argv[2], sys.argv[3])
        return
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--toolchain", help="toolchain profile JSON (replaces manifest tools one by one)")
    parser.add_argument("--manifest", help="tool manifest (default config/toolchain.json)")
    parser.add_argument("--no-tools", action="store_true", help="do not download; use what is already in build/tools")
    parser.add_argument("--force-split", action="store_true")
    sub = parser.add_subparsers(dest="command")
    swap_parser = sub.add_parser("swap", help="give one function a C translation unit")
    swap_parser.add_argument("function", help="function name or 0xADDRESS")
    swap_parser.add_argument("--src", help="C file to install as the unit")
    swap_parser.add_argument("--unit", help="unit name in splits.txt (default main/<function>.c)")
    args = parser.parse_args()
    tools = resolve_tools(args)
    if args.command == "swap":
        swap(args)
        args.force_split = True
    run_split(tools, args.force_split)
    config = json.loads((ROOT / OUT / "config.json").read_text())
    compiled = write_build(tools, config)
    write_objdiff(config, compiled)
    units = len(config["units"]) + sum(len(m["units"]) for m in config.get("modules", []))
    print(f"configured: {units} units, {len(config.get('modules', []))} module(s), {len(compiled)} with C; run `ninja`")


if __name__ == "__main__":
    main()
